29	constexpr std::string_view kTagUsage =
30	    "Usage: messagetag tag --key-hex <hex-key> --file <message-file>\n"
31	    "       (a <message-file> of exactly '-' reads the message from "
32	    "standard input)\n";
33	
34	constexpr std::string_view kVerifyUsage =
35	    "Usage: messagetag verify --key-hex <hex-key> --file <message-file> "
36	    "--tag-hex <hex-tag>\n"
37	    "       (a <message-file> of exactly '-' reads the message from "
38	    "standard input)\n";
39	
40	// Per-command identity for the shared option/prepare/authenticate flow:
41	// the name spliced into diagnostics, that command's own usage line and
42	// exactly the value-taking options it accepts. Whether a token following
43	// an option counts as "missing a value" is decided against this list, so
44	// each command keeps judging missing values by its own option set and a
45	// diagnostic for one command never carries the other command's usage.
46	struct CommandSpec {
47	    std::string_view name;
48	    std::string_view usage;
49	    std::vector<std::string_view> options;
50	};
51	
52	const CommandSpec& tagSpec() {
53	    static const CommandSpec spec{
54	        "tag", kTagUsage, {"--key-hex", "--file"}};
55	    return spec;
56	}
57	
58	const CommandSpec& verifySpec() {
59	    static const CommandSpec spec{
60	        "verify", kVerifyUsage,
61	        {"--key-hex", "--file", "--tag-hex"}};
62	    return spec;
63	}
64	
65	// SHA-256 HMAC tags are always 32 bytes / 64 hex characters.
66	constexpr std::size_t kTagBytes = 32;
67	
68	// Decode hexadecimal into raw bytes: every two characters are one byte and
69	// leading zeros must be preserved (e.g. "0001" is two bytes, not the number
70	// 1). Only digits and a-f/A-F are accepted; empty input, odd length,
71	// whitespace and a 0x prefix are rejected.
72	bool decodeHex(std::string_view hex, std::vector<unsigned char>& bytes) {
73	    if (hex.empty() || hex.size() % 2 != 0) {
74	        return false;
75	    }
76	    auto nibble = [](char c) -> int {
77	        if (c >= '0' && c <= '9') return c - '0';
78	        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
79	        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
80	        return -1;
81	    };
82	    bytes.clear();
83	    bytes.reserve(hex.size() / 2);
84	    for (std::size_t i = 0; i < hex.size(); i += 2) {
85	        int hi = nibble(hex[i]);
86	        int lo = nibble(hex[i + 1]);
87	        if (hi < 0 || lo < 0) {
88	            return false;
89	        }
90	        bytes.push_back(static_cast<unsigned char>((hi << 4) | lo));
91	    }
92	    return true;
93	}
94	
95	std::string hexEncode(const unsigned char* data, std::size_t length) {
96	    static constexpr char kHex[] = "0123456789abcdef";
97	    std::string out;
98	    out.resize(length * 2);
99	    for (std::size_t i = 0; i < length; ++i) {
100	        out[2 * i] = kHex[data[i] >> 4];
101	        out[2 * i + 1] = kHex[data[i] & 0x0F];
102	    }
103	    return out;
104	}
105	
106	// Write every byte of the one-line success result to file descriptor 1.
107	// This deliberately bypasses std::cout: the write can fail while the
108	// stream buffer is flushed, i.e. after the program has already "printed"
109	// the whole line. A short write of the remaining bytes is continued (pipes
110	// and space-constrained files legitimately accept partial counts); only
111	// EINTR is retried after a failed call, so EPIPE/ENOSPC/EIO terminate the
112	// attempt immediately. Bytes already accepted by the kernel cannot be
113	// taken back and are not re-emitted.
114	bool writeAllFd(int fd, std::string_view data) {
115	    std::size_t written = 0;
116	    while (written < data.size()) {
117	        ssize_t n = ::write(fd, data.data() + written, data.size() - written);
118	        if (n > 0) {
119	            written += static_cast<std::size_t>(n);
120	            continue;
121	        }
122	        if (n < 0 && errno == EINTR) {
123	            continue;
124	        }
125	        return false;
126	    }
127	    return true;
128	}
129	
130	// Output the single success line and make the exit code depend on it: a
131	// correctly computed tag, or a passed comparison, is not success unless
132	// the complete line (including the trailing newline) has actually reached
133	// standard output. On failure emits exactly one diagnostic that names the
134	// result-output stage -- never the key, the supplied tag or a recomputed
135	// tag -- and returns false so the caller exits 1. The errno text is saved
136	// before anything else can clobber errno.
137	bool emitResultLine(std::string_view command, std::string_view line) {
138	    if (writeAllFd(STDOUT_FILENO, line)) {
139	        return true;
140	    }
141	    int savedErrno = errno;
142	    // One single line, naming only the result-output stage. No key, tag or
143	    // recomputed tag is referenced, and no usage text follows.
144	    std::cerr << "messagetag " << command
145	              << ": error: standard output write failed while outputting "
146	                 "the result (" << std::strerror(savedErrno) << ")\n";
147	    return false;
148	}
149	
150	// Parse options of the form "--name value" starting at argv[2]. On a usage
151	// problem (an unknown argument, or an option without a following value) a
152	// command-specific diagnostic and the usage line are written to stderr and
153	// this returns false; the caller then exits with code 2. On success the
154	// collected values are stored keyed by option name, and the caller checks
155	// which required options are present. Only the value-taking options named
156	// in `names` are accepted.
157	//
158	// An option's value is missing not only when nothing follows it, but also
159	// when the next token is itself one of this command's option names: in
160	// "--file --file" the second "--file" is another option, not a file name,
161	// so the first "--file" is reported as missing a value instead of
162	// consuming the option as its value. Only an exact match with a recognized
163	// option name triggers this; any other token (including one that merely
164	// starts with a dash, such as "--notes", and including an explicitly empty
165	// string) is taken as the value, so file paths with leading dashes stay
166	// usable and empty values keep their own distinct diagnostics.
167	bool parseValueOptions(const CommandSpec& spec, int argc, char* argv[],
168	                       std::map<std::string, std::string>& values) {
169	    auto isOptionName = [&spec](std::string_view arg) {
170	        for (std::string_view name : spec.options) {
171	            if (arg == name) {
172	                return true;
173	            }
174	        }
175	        return false;
176	    };
177	    for (int i = 2; i < argc; ++i) {
178	        std::string arg(argv[i]);
179	        if (!isOptionName(arg)) {
180	            std::cerr << "messagetag " << spec.name
181	                      << ": error: unknown argument '" << arg << "'\n"
182	                      << spec.usage;
183	            return false;
184	        }
185	        // The diagnostic names only the option that lacks a value; the
186	        // following token (a recognized option name, or nothing at all) is
187	        // never spliced into the message, and neither is any key or tag
188	        // material supplied elsewhere on the command line.
189	        if (i + 1 >= argc || isOptionName(argv[i + 1])) {
190	            std::cerr << "messagetag " << spec.name
191	                      << ": error: option '" << arg
192	                      << "' requires a value\n"
193	                      << spec.usage;
194	            return false;
195	        }
196	        values[arg] = argv[++i];
197	    }
198	    return true;
199	}
200	
201	bool requireOption(const CommandSpec& spec,
202	                   const std::map<std::string, std::string>& values,
203	                   std::string_view name) {
204	    if (values.find(std::string(name)) == values.end()) {
205	        std::cerr << "messagetag " << spec.name
206	                  << ": error: missing required option '" << name << "'\n"
207	                  << spec.usage;
208	        return false;
209	    }
210	    return true;
211	}
