213	// Decode the --key-hex argument, emitting the shared key-format diagnostic
214	// (which never echoes the submitted key) on failure.
215	bool parseKey(const CommandSpec& spec, const std::string& keyHex,
216	              std::vector<unsigned char>& key) {
217	    if (decodeHex(keyHex, key)) {
218	        return true;
219	    }
220	    std::cerr << "messagetag " << spec.name
221	              << ": error: invalid --key-hex: expected a non-empty, "
222	                 "even-length string of hexadecimal characters (0-9, a-f, A-F); "
223	                 "every two characters denote one key byte and leading zeros must "
224	                 "be kept; a 0x prefix and whitespace are not accepted\n"
225	              << spec.usage;
226	    return false;
227	}
