229	// Stream a message into HMAC-SHA-256 a fixed-size chunk at a time. The
230	// message is never stored whole: regardless of its length, only one 64 KiB
231	// read buffer is needed on top of the constant-size HMAC context.
232	//
233	// The bytes are not interpreted as text: trailing newlines are kept, line
234	// endings are not converted and zero bytes are preserved. An empty input
235	// simply yields no Update calls, which authenticates the empty message.
236	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
237	
238	// A streaming HMAC-SHA-256 computation: Init with the key at construction,
239	// feed message bytes chunk by chunk with update(), produce the tag once
240	// with finish(). The file and standard-input sources both feed their bytes
241	// through this one path, so the same key and the same bytes always yield
242	// the same tag no matter which source they came from, and no matter how
243	// the input was split into reads.
244	//
245	// HMAC_Init_ex performs the standard RFC 2104 key normalization itself, so
246	// keys longer than the SHA-256 block size are hashed exactly as the
247	// standard requires; the resulting tag is identical to the one-shot HMAC()
248	// interface on both OpenSSL 1.1.1 and OpenSSL 3.x. The key is validated to
249	// be non-empty before this is constructed, so key.data() is always valid.
250	class HmacSha256Stream {
251	  public:
252	    explicit HmacSha256Stream(const std::vector<unsigned char>& key)
253	        : ctx_(HMAC_CTX_new(), &HMAC_CTX_free) {
254	        usable_ = ctx_ != nullptr &&
255	                  HMAC_Init_ex(ctx_.get(), key.data(),
256	                               static_cast<int>(key.size()), EVP_sha256(),
257	                               nullptr) == 1;
258	    }
259	
260	    bool usable() const { return usable_; }
261	
262	    bool update(const char* data, std::size_t length) {
263	        return HMAC_Update(ctx_.get(),
264	                           reinterpret_cast<const unsigned char*>(data),
265	                           length) == 1;
266	    }
267	
268	    bool finish(std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
269	                std::size_t& macLength) {
270	        unsigned int outLength = 0;
271	        if (HMAC_Final(ctx_.get(), mac.data(), &outLength) != 1) {
272	            return false;
273	        }
274	        macLength = outLength;
275	        return true;
276	    }
277	
278	  private:
279	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx_;
280	    bool usable_ = false;
281	};
282	
283	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
284	                          const std::string& path,
285	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
286	                          std::size_t& macLength) {
287	    HmacSha256Stream hmac(key);
288	    if (!hmac.usable()) {
289	        return HmacStatus::kCryptoError;
290	    }
291	
292	    std::ifstream in(path, std::ios::binary | std::ios::in);
293	    if (!in) {
294	        return HmacStatus::kReadError;
295	    }
296	
297	    std::array<char, 65536> buffer{};
298	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
299	        if (!hmac.update(buffer.data(),
300	                         static_cast<std::size_t>(in.gcount()))) {
301	            return HmacStatus::kCryptoError;
302	        }
303	    }
304	    // A read error (including one that happens after part of the message has
305	    // already been fed to HMAC) aborts authentication: finish() is never
306	    // called, so no partial-message tag can be produced. EOF with a short
307	    // final read is normal and those remaining bytes must still participate.
308	    if (in.bad()) {
309	        return HmacStatus::kReadError;
310	    }
311	    if (in.gcount() > 0) {
312	        if (!hmac.update(buffer.data(),
313	                         static_cast<std::size_t>(in.gcount()))) {
314	            return HmacStatus::kCryptoError;
315	        }
316	    }
317	
318	    if (!hmac.finish(mac, macLength)) {
319	        return HmacStatus::kCryptoError;
320	    }
321	    return HmacStatus::kSuccess;
322	}
323	
324	// Stream standard input (file descriptor 0) into HMAC-SHA-256 until the
325	// input ends normally (EOF). Selected by "--file -": every byte delivered
326	// before the end of input is part of the message, exactly as with a file --
327	// zero bytes and what follows them, trailing newlines and every line-ending
328	// form are authenticated unchanged, nothing is trimmed or converted, no
329	// line ending terminates the message early, and an empty input is the
330	// empty message. Bytes arriving in several installments are simply several
331	// update() calls, which does not change the tag. Only one fixed-size
332	// buffer is used no matter how long the input runs, and nothing is
333	// written to standard output while the input is still open.
334	//
335	// A read error -- including one after a non-empty prefix has already been
336	// fed to HMAC -- aborts authentication: finish() is never called, so the
337	// received prefix can never be finalized as if it were the whole message.
338	HmacStatus hmacSha256Stdin(const std::vector<unsigned char>& key,
339	                           std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
340	                           std::size_t& macLength) {
341	    HmacSha256Stream hmac(key);
342	    if (!hmac.usable()) {
343	        return HmacStatus::kCryptoError;
344	    }
345	
346	    std::array<char, 65536> buffer{};
347	    for (;;) {
348	        ssize_t n = ::read(STDIN_FILENO, buffer.data(), buffer.size());
349	        if (n > 0) {
350	            if (!hmac.update(buffer.data(), static_cast<std::size_t>(n))) {
351	                return HmacStatus::kCryptoError;
352	            }
353	            continue;
354	        }
355	        if (n == 0) {
356	            break;  // clean end of input: every byte has been fed
357	        }
358	        if (errno == EINTR) {
359	            continue;  // interrupted before any byte arrived; retry
360	        }
361	        return HmacStatus::kReadError;
362	    }
363	
364	    if (!hmac.finish(mac, macLength)) {
365	        return HmacStatus::kCryptoError;
366	    }
367	    return HmacStatus::kSuccess;
368	}
