370	// Output of the shared preparation stage that the command-specific
371	// decision still needs afterwards.
372	struct PreparedAuthentication {
373	    // verify only: the supplied --tag-hex decoded to 32 bytes; unused by
374	    // tag, which has no tag to compare against.
375	    std::vector<unsigned char> expectedTag;
376	};
377	
378	// Prepare and perform the message authentication that both commands share.
379	// This is the single place that maintains the ordered checks leading up to
380	// the command-specific result:
381	//
382	//   1. parse exactly this command's value-taking options (unknown argument
383	//      or missing value -> exit 2 with that command's usage);
384	//   2. require --key-hex/--file, and additionally --tag-hex when
385	//      `expectTag` is set (exit 2);
386	//   3. decode the key, and the supplied tag for verify, BEFORE the message
387	//      source is touched, so a malformed key/tag is a parameter error
388	//      (exit 2) even when the file does not exist -- and, with "--file -",
389	//      without waiting for standard input to arrive or end;
390	//   4. stream the whole message through HMAC-SHA-256, from the named file
391	//      or -- when --file is exactly "-" -- from standard input until its
392	//      normal end (read or computation failure -> exit 1, with no result
393	//      produced; a prefix read before a failure is never finalized as the
394	//      message).
395	//
396	// Every diagnostic goes out from here under the failing command's own name
397	// and usage, so one and the same failure behaviour no longer has to be kept
398	// in sync between runTag and runVerify. Returns the process exit code; on
399	// success it is 0 and `mac`/`macLength` (plus `prepared` for verify) hold
400	// what the caller needs for its own result handling; otherwise the caller
401	// returns the non-zero code unchanged.
402	int prepareAuthentication(const CommandSpec& spec, int argc, char* argv[],
403	                          bool expectTag,
404	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
405	                          std::size_t& macLength,
406	                          PreparedAuthentication& prepared) {
407	    std::map<std::string, std::string> opts;
408	    if (!parseValueOptions(spec, argc, argv, opts)) {
409	        return 2;
410	    }
411	    if (!requireOption(spec, opts, "--key-hex") ||
412	        !requireOption(spec, opts, "--file") ||
413	        (expectTag && !requireOption(spec, opts, "--tag-hex"))) {
414	        return 2;
415	    }
416	    const std::string& keyHex = opts["--key-hex"];
417	    const std::string& filePath = opts["--file"];
418	
419	    // All input-format checks happen before the message source is touched,
420	    // so a malformed key or tag is reported as a parameter error (exit 2)
421	    // even when the message file does not exist -- and, with "--file -",
422	    // without ever waiting for standard input.
423	    std::vector<unsigned char> key;
424	    if (!parseKey(spec, keyHex, key)) {
425	        return 2;
426	    }
427	
428	    if (expectTag) {
429	        // The supplied tag must decode to exactly 32 bytes (64 hex
430	        // characters); decodeHex already rejects empty input, odd length,
431	        // non-hex characters and whitespace, which also rules out a 0x
432	        // prefix. The submitted tag is deliberately not echoed back.
433	        if (!decodeHex(opts["--tag-hex"], prepared.expectedTag) ||
434	            prepared.expectedTag.size() != kTagBytes) {
435	            std::cerr << "messagetag " << spec.name
436	                      << ": error: invalid --tag-hex: expected exactly 64 "
437	                         "hexadecimal characters denoting 32 bytes (0-9, a-f, "
438	                         "A-F); empty, truncated or over-long values, embedded "
439	                         "whitespace and a 0x prefix are not accepted\n"
440	                      << spec.usage;
441	            return 2;
442	        }
443	    }
444	
445	    // A --file value of exactly "-" reads the message from standard input
446	    // until its normal end; a file literally named "-" stays reachable as
447	    // "./-" or by full path, and every other value is a file path read the
448	    // usual way.
449	    const bool fromStdin = filePath == "-";
450	    const HmacStatus status =
451	        fromStdin ? hmacSha256Stdin(key, mac, macLength)
452	                  : hmacSha256File(key, filePath, mac, macLength);
453	    switch (status) {
454	        case HmacStatus::kReadError:
455	            // The partially read prefix must never be authenticated as if
456	            // it were the whole message. Neither diagnostic echoes the key,
457	            // the supplied tag or a recomputed tag.
458	            if (fromStdin) {
459	                std::cerr << "messagetag " << spec.name
460	                          << ": error: failed to read standard input\n";
461	            } else {
462	                std::cerr << "messagetag " << spec.name
463	                          << ": error: failed to read file: " << filePath
464	                          << "\n";
465	            }
466	            return 1;
467	        case HmacStatus::kCryptoError:
468	            std::cerr << "messagetag " << spec.name
469	                      << ": error: HMAC-SHA-256 computation failed\n";
470	            return 1;
471	        case HmacStatus::kSuccess:
472	            return 0;
473	    }
474	    return 1;  // unreachable: every status is handled above
475	}
476	
477	int runTag(int argc, char* argv[]) {
478	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
479	    std::size_t macLength = 0;
480	    PreparedAuthentication prepared;
481	    int rc = prepareAuthentication(tagSpec(), argc, argv, /*expectTag=*/false,
482	                                   mac, macLength, prepared);
483	    if (rc != 0) {
484	        return rc;
485	    }
486	
487	    std::string tagLine = hexEncode(mac.data(), macLength);
488	    tagLine.push_back('\n');
489	    // Exit 0 only once the whole line is confirmed written; a correct tag
490	    // does not make a failed/partial result output a success.
491	    if (!emitResultLine("tag", tagLine)) {
492	        return 1;
493	    }
494	    return 0;
495	}
496	
497	// Compare two fixed-length byte strings without leaking the length of any
498	// matching prefix: the loop always touches every byte and accumulates all
499	// differences, so the running time does not depend on where (or whether)
500	// the inputs differ.
501	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
502	                       std::size_t length) {
503	    unsigned char diff = 0;
504	    for (std::size_t i = 0; i < length; ++i) {
505	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
506	    }
507	    return diff == 0;
508	}
509	
510	int runVerify(int argc, char* argv[]) {
511	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
512	    std::size_t macLength = 0;
513	    PreparedAuthentication prepared;
514	    int rc = prepareAuthentication(verifySpec(), argc, argv,
515	                                   /*expectTag=*/true, mac, macLength,
516	                                   prepared);
517	    if (rc != 0) {
518	        return rc;
519	    }
520	
521	    if (macLength != kTagBytes ||
522	        !constantTimeEqual(mac.data(), prepared.expectedTag.data(),
523	                           kTagBytes)) {
524	        // State only that authentication failed; do not assign a cause (the
525	        // message, the key or the tag could each be the one that differs),
526	        // and never print the recomputed tag, a matched prefix or the key.
527	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
528	                     "the supplied tag does not match the given key and file "
529	                     "content\n";
530	        return 3;
531	    }
532	
533	    // Exit 0 only once the whole "OK\n" line is confirmed written; a
534	    // passed comparison does not make a failed/partial result output a
535	    // success.
536	    if (!emitResultLine("verify", "OK\n")) {
537	        return 1;
538	    }
539	    return 0;
540	}
