544	int main(int argc, char* argv[]) {
545	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
546	        std::cout << "messagetag 0.1.0\n";
547	        return 0;
548	    }
549	    if (argc >= 2 && (std::string_view(argv[1]) == "tag" ||
550	                      std::string_view(argv[1]) == "verify")) {
551	        // A closed downstream pipe must surface as an EPIPE write failure
552	        // (reported and mapped to exit 1), not as the default SIGPIPE kill,
553	        // which would leave the shell with a signal-terminated status and
554	        // no diagnostic. Ignore SIGPIPE so write(2) returns EPIPE instead.
555	        std::signal(SIGPIPE, SIG_IGN);
556	        if (std::string_view(argv[1]) == "tag") {
557	            return runTag(argc, argv);
558	        }
559	        return runVerify(argc, argv);
560	    }
561	    std::cerr << "Usage: messagetag --version\n"
562	              << "       messagetag tag --key-hex <hex-key> "
563	                 "--file <message-file>\n"
564	              << "       messagetag verify --key-hex <hex-key> "
565	                 "--file <message-file> --tag-hex <hex-tag>\n"
